function showTopLeftToast(text) {
  const toast = document.getElementById("top-left-toast");
  const lbl = document.getElementById("top-left-toast-text");
  if (!toast || !lbl) return;
  lbl.textContent = text;
  toast.style.display = "flex";
  clearTimeout(window.__toastTimer);
  window.__toastTimer = setTimeout(() => { toast.style.display = "none"; }, 3200);
}

