function drawSignpost(ctx, ex) {
  ctx.save();
  ctx.translate(ex.x, ex.y);
  const isLeft = ex.x < 400;
  // Wooden post & finial cap
  ctx.fillStyle = "#5c4328";
  ctx.strokeStyle = "#2d1f11";
  ctx.lineWidth = 2;
  ctx.fillRect(-6, -112, 12, 112);
  ctx.strokeRect(-6, -112, 12, 112);
  ctx.beginPath();
  ctx.arc(0, -116, 8, 0, Math.PI * 2);
  ctx.fill(); ctx.stroke();

  // Split adjacent street names into directional arrow signboards
  const parts = String(ex.label).split("/").map(s => s.trim());
  parts.forEach((lbl, idx) => {
    const sy = -102 + idx * 32;
    ctx.fillStyle = idx === 0 ? "#6e4e2e" : "#593e23";
    ctx.strokeStyle = "#d4b483";
    ctx.lineWidth = 2;
    ctx.beginPath();
    if (isLeft) {
      ctx.moveTo(58, sy);
      ctx.lineTo(-56, sy);
      ctx.lineTo(-74, sy + 12);
      ctx.lineTo(-56, sy + 24);
      ctx.lineTo(58, sy + 24);
    } else {
      ctx.moveTo(-58, sy);
      ctx.lineTo(56, sy);
      ctx.lineTo(74, sy + 12);
      ctx.lineTo(56, sy + 24);
      ctx.lineTo(-58, sy + 24);
    }
    ctx.closePath();
    ctx.fill(); ctx.stroke();

    ctx.fillStyle = "#fff8e7";
    ctx.font = "bold 11px 'Trebuchet MS', sans-serif";
    ctx.textAlign = "center";
    ctx.fillText((isLeft ? "← " : "") + lbl + (!isLeft ? " →" : ""), 0, sy + 16);
  });
  ctx.restore();
}

